import { tags } from "typia";

import { IHrmPlatformEmployee } from "./IHrmPlatformEmployee";
import { IHrmPlatformProject } from "./IHrmPlatformProject";

/**
 * Comprehensive employee statistics for the organization dashboard. Provides aggregated metrics about workforce health, utilization, and pending management actions including employee counts by status and employment type, time tracking metrics for the current week, timesheet workflow status, and budget utilization warnings for projects exceeding 80% capacity.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IHrmPlatformEmployeeStatistic = {
  /**
   * Total number of employees in the organization, including both active and deactivated employees.
   *
   * @x-autobe-specification Query hrm_platform_employees table: COUNT(*) WHERE organization_id = {current_org_id} AND deleted_at IS NULL. This counts all employee records (both active and deactivated) that belong to the current organization, excluding soft-deleted records.
   */
  total_employees: number & tags.Type<"int32">;

  /**
   * Number of employees with active status who can currently work and submit timesheets.
   *
   * @x-autobe-specification Query hrm_platform_employees table: COUNT(*) WHERE organization_id = {current_org_id} AND status = 'active' AND deleted_at IS NULL. This counts only employees with active status who can currently log time and submit timesheets.
   */
  active_employees: number & tags.Type<"int32">;

  /**
   * Number of employees with deactivated status whose historical data is preserved.
   *
   * @x-autobe-specification Query hrm_platform_employees table: COUNT(*) WHERE organization_id = {current_org_id} AND status = 'deactivated' AND deleted_at IS NULL. This counts employees who have been deactivated but whose historical records are preserved.
   */
  deactivated_employees: number & tags.Type<"int32">;

  /**
   * Breakdown of employee counts by employment type classification: full-time, part-time, contractor, and intern.
   *
   * @x-autobe-specification Query hrm_platform_employees table: COUNT(*) GROUP BY employment_type WHERE organization_id = {current_org_id} AND deleted_at IS NULL. Returns object with four keys: full_time, part_time, contractor, intern. Each key contains the count of employees with that employment type. Ensure all four keys are present even if count is zero.
   */
  by_employment_type: {
    full_time: number & tags.Type<"int32">;
    part_time: number & tags.Type<"int32">;
    contractor: number & tags.Type<"int32">;
    intern: number & tags.Type<"int32">;
  };

  /**
   * Total hours logged across all employees in the current week (Monday-Sunday).
   *
   * @x-autobe-specification Query hrm_platform_timelogs table: SUM(duration)/60 WHERE employee_id IN (SELECT id FROM hrm_platform_employees WHERE organization_id = {current_org_id}) AND date >= {current_week_monday} AND date <= {current_week_sunday}. Duration is stored in minutes, divide by 60 to get hours. Returns total hours logged across all employees for the current calendar week (Monday to Sunday).
   */
  total_hours_this_week: number;

  /**
   * Average hours logged per active employee in the current week.
   *
   * @x-autobe-specification Query hrm_platform_timelogs JOIN hrm_platform_employees: AVG(SUM(duration)/60) GROUP BY employee_id WHERE organization_id = {current_org_id} AND status = 'active' AND deleted_at IS NULL AND date >= {current_week_monday} AND date <= {current_week_sunday}. Calculate average of hours logged per active employee for the current week. Return 0 if no active employees have logged time.
   */
  average_hours_per_employee: number;

  /**
   * Top 5 employees by hours logged in the current week, returned as employee summary objects.
   *
   * @x-autobe-specification Query hrm_platform_timelogs JOIN hrm_platform_employees: SELECT employee.*, SUM(duration)/60 as total_hours WHERE organization_id = {current_org_id} AND status = 'active' AND deleted_at IS NULL AND date >= {current_week_monday} AND date <= {current_week_sunday} GROUP BY employee_id ORDER BY total_hours DESC LIMIT 5. Return array of IHrmPlatformEmployee.ISummary objects for the top 5 employees by hours logged in the current week.
   */
  top_performers: IHrmPlatformEmployee.ISummary[] & tags.MaxItems<5>;

  /**
   * Number of timesheets awaiting approval from managers.
   *
   * @x-autobe-specification Query hrm_platform_timesheets table: COUNT(*) WHERE employee_id IN (SELECT id FROM hrm_platform_employees WHERE organization_id = {current_org_id}) AND status = 'submitted'. Count timesheets that have been submitted by employees and are awaiting manager approval.
   */
  pending_timesheets: number & tags.Type<"int32">;

  /**
   * Number of timesheets approved this week.
   *
   * @x-autobe-specification Query hrm_platform_timesheets table: COUNT(*) WHERE employee_id IN (SELECT id FROM hrm_platform_employees WHERE organization_id = {current_org_id}) AND status = 'approved' AND week_start >= {current_week_monday} AND week_start <= {current_week_sunday}. Count timesheets that were approved during the current week.
   */
  approved_timesheets: number & tags.Type<"int32">;

  /**
   * Number of timesheets rejected this week.
   *
   * @x-autobe-specification Query hrm_platform_timesheets table: COUNT(*) WHERE employee_id IN (SELECT id FROM hrm_platform_employees WHERE organization_id = {current_org_id}) AND status = 'rejected' AND week_start >= {current_week_monday} AND week_start <= {current_week_sunday}. Count timesheets that were rejected during the current week.
   */
  rejected_timesheets: number & tags.Type<"int32">;

  /**
   * List of projects exceeding 80% budget utilization, returned as project summary objects.
   *
   * @x-autobe-specification Query hrm_platform_projects JOIN hrm_platform_timelogs: SELECT project.*, (SUM(timelog.duration)/60) / project.budget_hours * 100 as utilization WHERE organization_id = {current_org_id} AND project.budget_hours IS NOT NULL AND project.deleted_at IS NULL GROUP BY project.id HAVING utilization > 80. Return array of IHrmPlatformProject.ISummary objects for projects exceeding 80% budget utilization. Exclude projects without budget_hours defined.
   */
  budget_warnings: IHrmPlatformProject.ISummary[];

  /**
   * Timestamp when these statistics were generated and cached.
   *
   * @x-autobe-specification Server-generated timestamp using current database time: NOW() or CURRENT_TIMESTAMP. This timestamp indicates when the statistics were computed and cached. Format as ISO 8601 date-time string with timezone information.
   */
  generated_at: string & tags.Format<"date-time">;
};
